import{_ as a}from"./chunks/第一步-03.D7lAR9Hu.js";import{_ as o,o as r,c as t,a2 as d}from"./chunks/framework.CqGPl1zp.js";const c="/newx-doc/assets/%E7%AC%AC%E4%B8%80%E6%AD%A5-01.CdbLwyHP.png",l="/newx-doc/assets/%E7%AC%AC%E4%B8%80%E6%AD%A5-02.B2WD5P9v.png",i="/newx-doc/assets/%E7%AE%A1%E7%90%86%E5%90%8E%E5%8F%B0.CVWZOMRD.png",g=JSON.parse('{"title":"功能开启","description":"","frontmatter":{},"headers":[],"relativePath":"crm/build.md","filePath":"crm/build.md","lastUpdated":null}'),p={name:"crm/build.md"};function s(m,e,n,u,_,h){return r(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="功能开启" tabindex="-1">功能开启 <a class="header-anchor" href="#功能开启" aria-label="Permalink to &quot;功能开启&quot;">​</a></h1><p>进度说明：</p><ul><li>管理后台，请使用 <a href="https://gitee.com/yudaocode/yudao-ui-admin-vue3" target="_blank" rel="noreferrer">https://gitee.com/yudaocode/yudao-ui-admin-vue3</a> 仓库的 <code>master</code> 分支</li><li>后端项目，请使用 <a href="https://gitee.com/zhijiantianya/ruoyi-vue-pro" target="_blank" rel="noreferrer">https://gitee.com/zhijiantianya/ruoyi-vue-pro</a> 仓库的 <code>master</code>（JDK8）、<code>master-jdk17</code>（JDK17/21）或 <code>master-jdk25</code>（JDK25）分支</li></ul><p>CRM 系统，后端由 <code>yudao-module-crm</code> 模块实现，前端由 <code>yudao-ui-admin-vue3</code> 的 <code>crm</code> 目录实现。</p><p>考虑到编译速度，默认 <code>yudao-module-crm</code> 模块是关闭的，需要手动开启。步骤如下：</p><ul><li>第一步，开启 <code>yudao-module-crm</code> 模块</li><li>第二步，导入 CRM 系统的 SQL 数据库脚本</li><li>第三步，重启后端项目，确认功能是否生效</li></ul><p>补充说明：</p><p>由于 CRM 合同、回款使用到 BPM 的审批功能，所以你需要先看 <a href="./../bpm">《工作流》</a> 文档，将工作流开启！</p><h2 id="_1-第一步-开启模块" tabindex="-1">1. 第一步，开启模块 <a class="header-anchor" href="#_1-第一步-开启模块" aria-label="Permalink to &quot;1. 第一步，开启模块&quot;">​</a></h2><p>① 修改根目录的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/pom.xml" target="_blank" rel="noreferrer"><code>pom.xml</code></a> 文件，取消 <code>yudao-module-crm</code> 模块的注释。如下图所示：</p><p><img src="'+c+'" alt="取消  模块的注释"></p><p>② 修改 <code>yudao-server</code> 目录的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-server/pom.xml" target="_blank" rel="noreferrer"><code>pom.xml</code></a> 文件，引入 <code>yudao-module-crm</code> 模块。如下图所示：</p><p><img src="'+l+'" alt="引入  模块"></p><p>③ 点击 IDEA 右上角的【Reload All Maven Projects】，刷新 Maven 依赖。如下图所示：</p><p><img src="'+a+'" alt="刷新 Maven 依赖"></p><h2 id="_2-第二步-导入-sql" tabindex="-1">2. 第二步，导入 SQL <a class="header-anchor" href="#_2-第二步-导入-sql" aria-label="Permalink to &quot;2. 第二步，导入 SQL&quot;">​</a></h2><p>点击 <a href="https://lwb8832652.github.io/newx-doc/sql/crm.sql" target="_blank" rel="noreferrer">下载 SQL</a> 直接下载 SQL 文件，导入到数据库中。</p><p>友情提示：↑↑↑ crm.sql 是可以点击下载的！ ↑↑↑</p><p>重要说明：该 SQL 仅芋道星球成员可使用和商用，否则视为侵权（索赔 100 万，永久追溯）【下载即视为同意】。</p><p>所以表名字，都使用 <code>crm_</code> 作为前缀。</p><h2 id="_3-第三步-重启项目" tabindex="-1">3. 第三步，重启项目 <a class="header-anchor" href="#_3-第三步-重启项目" aria-label="Permalink to &quot;3. 第三步，重启项目&quot;">​</a></h2><p>重启后端项目，然后访问前端的 CRM 菜单，确认功能是否生效。如下图所示：</p><p><img src="'+i+'" alt="确认功能是否生效"></p><p>至此，我们就成功开启了 CRM 的功能 🙂</p>',24)])])}const y=o(p,[["render",s]]);export{g as __pageData,y as default};
